catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    // If Select all check box is checked, check all the H&S Checklist boxes, otherwise uncheck them
    if (newValue == 'true') {
        g_form.setValue("ohs_checklist_telework_1", true);
        g_form.setValue("ohs_checklist_telework_2", true);
        g_form.setValue("ohs_checklist_telework_3", true);
        g_form.setValue("ohs_checklist_telework_4", true);
        g_form.setValue("ohs_checklist_telework_5", true);
        g_form.setValue("ohs_checklist_telework_6", true);
        g_form.setValue("ohs_checklist_safety_1", true);
        g_form.setValue("ohs_checklist_safety_2", true);
        g_form.setValue("ohs_checklist_safety_3", true);
        g_form.setValue("ohs_checklist_safety_4", true);
        g_form.setValue("ohs_checklist_emergency_1", true);
        g_form.setValue("ohs_checklist_emergency_2", true);
        g_form.setValue("ohs_checklist_emergency_3", true);
        g_form.setValue("ohs_checklist_emergency_4", true);
        g_form.setValue("ohs_checklist_emergency_5", true);
    } else {
        g_form.setValue("ohs_checklist_telework_1", false);
        g_form.setValue("ohs_checklist_telework_2", false);
        g_form.setValue("ohs_checklist_telework_3", false);
        g_form.setValue("ohs_checklist_telework_4", false);
        g_form.setValue("ohs_checklist_telework_5", false);
        g_form.setValue("ohs_checklist_telework_6", false);
        g_form.setValue("ohs_checklist_safety_1", false);
        g_form.setValue("ohs_checklist_safety_2", false);
        g_form.setValue("ohs_checklist_safety_3", false);
        g_form.setValue("ohs_checklist_safety_4", false);
        g_form.setValue("ohs_checklist_emergency_1", false);
        g_form.setValue("ohs_checklist_emergency_2", false);
        g_form.setValue("ohs_checklist_emergency_3", false);
        g_form.setValue("ohs_checklist_emergency_4", false);
        g_form.setValue("ohs_checklist_emergency_5", false);
    }
}
